mapper.select:
SELECT
it.id,
it.plan_id,
it.user_id,
it.dispatch_time,
it.claim_time,
it.status,
it.progress,
it.is_archive,
it.reserve1,
it.reserve2,
it.creator,
it.updater,
it.create_time,
it.update_time,
ip.name AS plan_name,  -- 从 inspect_plan 表获取计划名称
ip.type AS plan_type_name,  -- 从 inspect_plan 表获取类型名称
iu.name AS user_name   -- 从 inspect_user 表获取人员姓名
FROM inspect_task it
LEFT JOIN inspect_plan ip ON it.plan_id = ip.id
LEFT JOIN inspect_user iu ON it.user_id = iu.id



        AND it.plan_id = #{reqVO.planId}


        AND ip.type LIKE CONCAT('%', #{reqVO.planTypeName}, '%')



        AND it.user_id = #{reqVO.userId}




        AND it.dispatch_time BETWEEN #{reqVO.dispatchTime[0]} AND #{reqVO.dispatchTime[1]}




        AND it.claim_time BETWEEN #{reqVO.claimTime[0]} AND #{reqVO.claimTime[1]}







                AND it.status IN ('1', '2', '3')



                AND it.status = #{reqVO.status}






        AND it.progress = #{reqVO.progress}




        AND it.is_archive = #{reqVO.isArchive}




        AND it.reserve1 = #{reqVO.reserve1}




        AND it.reserve2 = #{reqVO.reserve2}




        AND it.creator = #{reqVO.creator}




        AND it.updater = #{reqVO.updater}




        AND it.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}




        AND it.update_time BETWEEN #{reqVO.updateTime[0]} AND #{reqVO.updateTime[1]}




        AND DATE_FORMAT(it.update_time, '%m') = #{reqVO.updateMonth}



    AND it.deleted = 0

ORDER BY it.id DESC

SELECT COALESCE(ip.type, '未分类') AS typeName, COUNT(*) AS count FROM inspect_task it LEFT JOIN inspect_plan ip ON it.plan_id = ip.id WHERE it.deleted = 0
AND it.create_time BETWEEN #{timeRange[0]} AND #{timeRange[1]}
GROUP BY ip.type ORDER BY count DESC

SELECT DATE_FORMAT(it.create_time, '%m') AS time, AVG( CASE WHEN it.status = '3' AND it.claim_time IS NOT NULL AND it.create_time IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, it.claim_time, it.create_time) ELSE 0 END ) AS avgHandleTime FROM inspect_task it WHERE it.deleted = 0
AND it.create_time BETWEEN #{timeRange[0]} AND #{timeRange[1]}
GROUP BY DATE_FORMAT(it.create_time, '%m') ORDER BY time
